mapper.sql:
ord_dir_deliv_request oddr
INNER JOIN ord_dir_order_cycle odoc on oddr.order_cycle_id=odoc.id and odoc.store_code=oddr.store_code and
odoc.biz_org_code=oddr.biz_org_code and odoc.is_delete=0
inner join opt_dir_order_type_config ootc on odoc.order_type_config_id=ootc.id and
odoc.biz_org_code=ootc.biz_org_code and ootc.is_delete=0

    inner join ord_dir_order odo on odo.request_order_id=oddr.id and odo.biz_org_code=#{bizOrgCode} and
    odo.is_delete=0


    inner join ord_dir_deliv_request_delivery oddrd on oddrd.request_order_id = oddr.id
    inner join ord_dir_delivery odd on odd.id = oddrd.delivery_order_id and odd.biz_org_code = #{bizOrgCode} and
    odd.is_delete = 0

where
oddr.biz_org_code = #{bizOrgCode} and oddr.is_delete = 0

    and oddr.request_order_no = #{requestOrderNo}


    and  date_format(oddr.create_time, '%Y-%m') =#{createMonth}


    and oddr.status_code = #{statusCode}


    and odoc.order_type_config_id = #{orderTypeConfigId}


    and odoc.order_type_config_id  in

        #{item}



    and oddr.store_code = #{storeCode}


    and oddr.store_code in

        #{item}



    and odo.order_no = #{orderNo}


    and odd.delivery_order_no = #{deliveryOrderNo}


    and oddr.truncation_date_time >= #{beginTruncationTime}


    and oddr.truncation_date_time <= #{endTruncationTime}


    and oddr.total_amount >= #{totalAmount}


    and oddr.total_amount <= #{totalAmount}


    and exists (
    SELECT
    1
    FROM
    ord_dir_deliv_request_detail oddrd
    WHERE oddrd.request_order_id = oddr.id
    AND oddrd.goods_code = #{goodsCode}
    AND oddrd.is_delete = 0
    )

mapper.select:
select group_concat(odd.delivery_order_no) from ord_dir_deliv_request_delivery oddrd
inner join ord_dir_delivery odd on odd.id = oddrd.delivery_order_id and odd.is_delete=0 and odd.biz_org_code=#{bizOrgCode}
where oddrd.request_order_id = #{requestOrderId}

select request_order_no from ord_dir_deliv_request
where create_time >= #{createTimeBegin} and create_time <= #{createTimeEnd}
  and status_code = #{statusCode}
  and biz_org_code = #{bizOrgCode}
  and is_delete = 0
